#!/usr/bin/env bash
# Debug APK through the gradle build (needed for the deep-link intent-filters, addons/deeplink).
# android/ is generated by Godot (1 GB, gitignored): the first run installs the build template.
# Prereq: src/tools/setup_android_toolchain.sh. Output: build/android/ab.apk
set -euo pipefail
cd "$(dirname "$0")/../.."
flag=()
[ -d android/build ] || flag=(--install-android-build-template)
mkdir -p build/android
godot --headless --path . "${flag[@]}" --export-debug Android build/android/ab.apk
